        width={640}>
        {selectedEt && (
          <div>
            {/* Sélecteur de classe */}
            <div style={{ display: 'flex', gap: 0, padding: '0 24px', borderBottom: '2px solid var(--gray-100)' }}>
              {[1,2].map(c => (
                <button key={c} type="button" onClick={() => setNoteData(prev => ({ ...prev, classe: c }))}
                  style={{ padding: '10px 24px', border: 'none', background: 'transparent', cursor: 'pointer',
                    fontSize: '0.85rem', fontWeight: 600,
                    color: noteData.classe === c ? 'var(--navy)' : 'var(--gray-400)',
                    borderBottom: noteData.classe === c ? '2px solid var(--gold)' : '2px solid transparent',
                    marginBottom: '-2px' }}>
                  📚 Classe {c}
                </button>
              ))}
            </div>

            {noteData.classe === 2 && (
              <div style={{ margin: '12px 24px 0', background: '#f0fdf4', border: '1px solid #86efac',
                borderRadius: 8, padding: '10px 14px', fontSize: '0.8rem', color: '#166534' }}>
                ℹ️ La Classe 2 est accessible uniquement si la Classe 1 est complète avec une moyenne ≥ 10/20.
                Le système vérifiera automatiquement.
              </div>
            )}

            <div style={{ padding: '20px 24px' }}>
              <p style={{ fontSize: '0.8rem', color: 'var(--gray-400)', marginBottom: 16 }}>
                Saisir les notes sur 20 pour chaque leçon (laisser vide si non encore évaluée)
              </p>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2,1fr)', gap: '12px 20px' }}>
                {LECONS.map(lecon => {
                  const val = noteData.classe === 1
                    ? (noteData.notes1?.[lecon] ?? '')
                    : (noteData.notes2?.[lecon] ?? '');
                  const num = parseFloat(val);
                  const color = val === '' ? 'var(--gray-200)' : (num >= 10 ? '#16a34a' : '#dc2626');
                  return (
                    <div key={lecon} style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                      <label style={{ fontSize: '0.82rem', fontWeight: 600, color: 'var(--navy)', minWidth: 65 }}>
                        Leçon {lecon}
                      </label>
                      <input
                        type="number" min="0" max="20" step="0.25"
                        value={val}
                        onChange={e => {
                          const k = noteData.classe === 1 ? 'notes1' : 'notes2';
                          setNoteData(prev => ({ ...prev, [k]: { ...prev[k], [lecon]: e.target.value } }));
                        }}
                        style={{ width: 80, textAlign: 'center', borderColor: color, fontWeight: 700,
                          color: val !== '' ? color : undefined }}
                        placeholder="—"
                      />
                      <span style={{ fontSize: '0.75rem', color: 'var(--gray-400)' }}>/20</span>
                      {val !== '' && (
                        <MentionBadge moyenne={val} />
                      )}
                    </div>
                  );
                })}
              </div>

              {/* Récap */}
              {(() => {
                const ns = noteData.classe === 1 ? noteData.notes1 : noteData.notes2;
                const vals = Object.values(ns||{}).filter(v => v !== '' && !isNaN(parseFloat(v)));
                if (!vals.length) return null;
                const total = vals.reduce((s,v) => s + parseFloat(v), 0);
                const moy   = total / vals.length;
                return (
                  <div style={{ marginTop: 16, padding: '12px 16px', background: 'var(--gray-50)',
                    borderRadius: 10, border: '1px solid var(--gray-200)', display: 'flex', gap: 20 }}>
                    <div><span style={{ fontSize: '0.75rem', color: 'var(--gray-400)' }}>Leçons saisies</span>
                      <p style={{ fontWeight: 700, color: 'var(--navy)' }}>{vals.length} / 10</p></div>
                    <div><span style={{ fontSize: '0.75rem', color: 'var(--gray-400)' }}>Total</span>
                      <p style={{ fontWeight: 700, color: 'var(--navy)' }}>{total.toFixed(2)}</p></div>
                    <div><span style={{ fontSize: '0.75rem', color: 'var(--gray-400)' }}>Moyenne</span>
                      <p style={{ fontWeight: 700, color: moy >= 10 ? '#16a34a' : '#dc2626' }}>{moy.toFixed(2)}/20</p></div>
                    <div><span style={{ fontSize: '0.75rem', color: 'var(--gray-400)' }}>Mention</span>
                      <MentionBadge moyenne={moy} /></div>
                  </div>
                );
              })()}
