        {selectedEt && (
          <div>
            {/* En-tête identité */}
            <div style={{ background: 'linear-gradient(135deg,#0f2044,#1a3a6e)', color: 'white',
              padding: '16px 24px', display: 'flex', gap: 16, alignItems: 'flex-start' }}>
              <div style={{ flex: 1 }}>
                <p style={{ fontFamily: "'Playfair Display',serif", fontSize: '1.2rem', fontWeight: 700 }}>
                  {selectedEt.prenom} {selectedEt.nom}
