                    {selectedEt.langue}
                  </span>
                  <span style={{ background: '#c9a84c', color: '#0f2044', padding: '2px 10px', borderRadius: 10,
                    fontSize: '0.78rem', fontWeight: 700, fontFamily: 'monospace' }}>
                    {selectedEt.numero_etudiant}
                  </span>
                  <span style={{ background: 'rgba(255,255,255,0.15)', padding: '2px 10px', borderRadius: 10, fontSize: '0.78rem' }}>
                    Classe {selectedEt.classe_actuelle}
                  </span>
                </div>
              </div>
              <div style={{ textAlign: 'right' }}>
                <p style={{ opacity: .7, fontSize: '0.72rem' }}>Inscription</p>
