            </div>

            <div style={{ padding: 24 }}>
              {/* Stats classes */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 20 }}>
                {[1,2].map(classe => {
                  const stats = selectedEt[`stats_classe_${classe}`];
                  if (!stats) return null;
                  const done = stats.complete;
                  const color = done ? (stats.valide ? '#16a34a' : '#dc2626') : 'var(--navy)';
                  return (
                    <div key={classe} style={{ border: '1px solid var(--gray-200)', borderRadius: 10,
                      padding: '14px 16px', background: done ? (stats.valide ? '#f0fdf4' : '#fef2f2') : 'var(--gray-50)' }}>
                      <p style={{ fontWeight: 700, color, fontSize: '0.9rem', marginBottom: 8 }}>
                        {done ? (stats.valide ? '✅' : '❌') : '📚'} Classe {classe}
                      </p>
                      <div style={{ display: 'flex', gap: 12, fontSize: '0.82rem', flexWrap: 'wrap' }}>
                        <div>
                          <p style={{ color: 'var(--gray-400)', fontSize: '0.72rem' }}>Leçons</p>
                          <p style={{ fontWeight: 700, color }}>{stats.lecons}/10</p>
                        </div>
                        {stats.moyenne !== null && (
                          <>
                            <div>
                              <p style={{ color: 'var(--gray-400)', fontSize: '0.72rem' }}>Moyenne</p>
                              <p style={{ fontWeight: 700, color }}>{stats.moyenne}/20</p>
                            </div>
                            <div>
                              <p style={{ color: 'var(--gray-400)', fontSize: '0.72rem', marginBottom: 2 }}>Mention</p>
                              <MentionBadge moyenne={stats.moyenne} />
                            </div>
                          </>
                        )}
                      </div>
                      {stats.lecons > 0 && (
                        <div style={{ marginTop: 8 }}>
                          <div style={{ height: 5, background: 'var(--gray-200)', borderRadius: 99, overflow: 'hidden' }}>
                            <div style={{ height: '100%', width: `${(stats.lecons/10)*100}%`,
                              background: color, borderRadius: 99 }} />
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>

              {/* Notes détail */}
              {[1,2].map(classe => {
                const ns = (selectedEt.notes||[]).filter(n => n.classe===classe).sort((a,b)=>a.lecon-b.lecon);
                if (!ns.length) return null;
                return (
                  <div key={classe} style={{ marginBottom: 16 }}>
                    <p style={{ fontSize: '0.78rem', fontWeight: 700, color: 'var(--gold-dark)',
                      textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 8 }}>
                      Classe {classe} — Détail des notes
                    </p>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5,1fr)', gap: 8 }}>
                      {ns.map(n => (
                        <div key={n.id} style={{ border: '1px solid var(--gray-200)', borderRadius: 8,
                          padding: '8px 10px', textAlign: 'center',
                          background: parseFloat(n.note) >= 10 ? '#f0fdf4' : '#fef2f2' }}>
                          <p style={{ fontSize: '0.68rem', color: 'var(--gray-400)', marginBottom: 2 }}>Leçon {n.lecon}</p>
                          <p style={{ fontSize: '1.1rem', fontWeight: 700,
                            color: parseFloat(n.note) >= 10 ? '#166534' : '#991b1b' }}>
                            {parseFloat(n.note).toFixed(2)}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>
                );
              })}

              {/* Infos supplémentaires */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '6px 20px', fontSize: '0.82rem' }}>
                {[
                  ['Adresse', selectedEt.adresse],
                  ['Téléphone', selectedEt.telephone],
                  ['Source info', selectedEt.source_info],
                  ['Volontaire responsable', selectedEt.volontaire_responsable],
                  ['Église', selectedEt.eglise?.nom],
                  ['Hiérarchie', selectedEt.eglise?.hierarchie],
                ].filter(([,v]) => v).map(([label, value]) => (
                  <div key={label}>
                    <span style={{ color: 'var(--gray-400)', fontSize: '0.72rem' }}>{label}</span>
                    <p style={{ fontWeight: 500, color: 'var(--navy)' }}>{value}</p>
                  </div>
                ))}
              </div>
            </div>

            <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end',
              padding: '14px 24px', borderTop: '1px solid var(--gray-100)', background: 'var(--gray-50)' }}>
              <Btn variant="secondary" onClick={() => { printBulletin(selectedEt); }}>🖨️ Imprimer le bulletin</Btn>
              {canEdit && (
                <Btn variant="gold" onClick={() => { setDetailModalOpen(false); openModal(selectedEt); }}>✏️ Modifier</Btn>
              )}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}
